//! Linear reduction of a complete closed horizontal visibility map.
//!
//! `Cell` caps are generated by original polygon vertices, not by horizontal
//! ray landing points. Exterior, wrapping, seam, padding, and null cells must
//! already have been removed. The input must contain every positive-area
//! interior cell, exactly once. Simplicity and pairwise distinct vertex Y are
//! caller preconditions; this module does not perform a quadratic validator.
//!
//! The all-cell support diagonals partition the polygon into mountains: each
//! remaining face has one original edge between its Y extrema and a monotone
//! opposite chain. At an ordinary vertex two cells have a cap, at a convex
//! extremum one does, and at a reflex extremum three do. Thus local rotation
//! insertion examines at most five darts; there is no global angular sort.
//! Face walks and strict-turn stacks visit each dart/chain vertex O(1) times.
//! See the per-trapezoid reduction in Toma's polygon triangulation lecture,
//! slides 79–89, and Fournier–Montuno (1984), DOI 10.1145/357337.357341.

use crate::geometry::{Point, Rational, orientation};
use crate::work::Work;
use num_traits::Zero;
use std::borrow::Borrow;
use std::cmp::Ordering;
use std::fmt;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Cell {
    pub generators: [usize; 2],
    pub left_edge: usize,
    pub right_edge: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ReductionError {
    InvalidPolygon,
    InvalidCellIndex { cell: usize },
    InvalidCellBoundary { cell: usize },
    InvalidCapIncidence { vertex: usize, expected: usize, actual: usize },
    OverlappingDirections { vertex: usize },
    InvalidEmbedding,
    NonMountain,
    IncorrectTriangleCount,
}

impl fmt::Display for ReductionError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidPolygon => write!(f, "polygon must have at least three vertices, nonzero area, and nonhorizontal nonbacktracking edges"),
            Self::InvalidCellIndex { cell } => write!(f, "visibility cell {cell} references an invalid original index"),
            Self::InvalidCellBoundary { cell } => write!(f, "visibility cell {cell} has invalid boundary supports or cap generators"),
            Self::InvalidCapIncidence { vertex, expected, actual } => write!(f, "vertex {vertex} generates {actual} caps, but its full visibility map requires {expected}"),
            Self::OverlappingDirections { vertex } => write!(f, "support diagonals overlap in a direction at vertex {vertex}"),
            Self::InvalidEmbedding => write!(f, "support diagonals do not give the required original-only embedding"),
            Self::NonMountain => write!(f, "support diagonals do not partition the polygon into monotone mountains"),
            Self::IncorrectTriangleCount => write!(f, "visibility reduction did not produce n-2 triangles"),
        }
    }
}
impl std::error::Error for ReductionError {}

#[derive(Clone, Copy)]
struct Dart {
    tail: usize,
    head: usize,
    twin: usize,
    rot_next: usize,
    rot_prev: usize,
}

fn turn(vertices: &[impl Borrow<Point>], a: usize, b: usize, c: usize, work: &mut Work) -> Ordering {
    work.predicates += 1;
    orientation(vertices[a].borrow(), vertices[b].borrow(), vertices[c].borrow())
}

fn edge_x(vertices: &[impl Borrow<Point>], edge: usize, y: &Rational) -> Rational {
    let a = vertices[edge].borrow();
    let b = vertices[(edge + 1) % vertices.len()].borrow();
    &a.x + (y - &a.y) * (&b.x - &a.x) / (&b.y - &a.y)
}

fn incident(edge: usize, vertex: usize, n: usize) -> bool {
    edge == vertex || (edge + 1) % n == vertex
}

fn boundary_pair(a: usize, b: usize, n: usize) -> bool {
    (a + 1) % n == b || (b + 1) % n == a
}

// Counterclockwise order, with its cut on the positive X ray. All endpoints
// have distinct Y, so neither direction lies on the cut or its opposite.
fn angular_cmp(vertices: &[impl Borrow<Point>], tail: usize, a: usize, b: usize, work: &mut Work) -> Ordering {
    work.predicates += 2;
    let a_upper = vertices[a].borrow().y > vertices[tail].borrow().y;
    let b_upper = vertices[b].borrow().y > vertices[tail].borrow().y;
    match b_upper.cmp(&a_upper) {
        Ordering::Equal => turn(vertices, tail, a, b, work).reverse(),
        order => order,
    }
}

fn splice_rotation(vertices: &[impl Borrow<Point>], darts: &mut [Dart], start: usize, new: usize, work: &mut Work) -> Result<(), ReductionError> {
    let tail = darts[new].tail;
    let head = darts[new].head;
    let mut current = start;
    loop {
        work.decomposition_visits += 1;
        let next = darts[current].rot_next;
        let left = angular_cmp(vertices, tail, darts[current].head, head, work);
        let right = angular_cmp(vertices, tail, head, darts[next].head, work);
        if left == Ordering::Equal || right == Ordering::Equal {
            return Err(ReductionError::OverlappingDirections { vertex: tail });
        }
        let gap = angular_cmp(vertices, tail, darts[current].head, darts[next].head, work);
        let inside = if gap == Ordering::Less {
            left == Ordering::Less && right == Ordering::Less
        } else {
            left == Ordering::Less || right == Ordering::Less
        };
        if inside {
            darts[new].rot_prev = current;
            darts[new].rot_next = next;
            darts[current].rot_next = new;
            darts[next].rot_prev = new;
            return Ok(());
        }
        current = next;
        if current == start {
            return Err(ReductionError::InvalidEmbedding);
        }
    }
}

/// Turn the complete closed interior visibility subdivision into original-ID
/// CCW triangles. Exact arithmetic costs are separate from the O(n) operation
/// bound. Invalid local cell contracts are rejected, but polygon simplicity and
/// global completeness/nonoverlap of the visibility subdivision are supplied
/// by the caller, not rediscovered by pairwise intersection tests here.
/// Owned points and borrowed point tables share the same noncopying path.
pub fn triangulate_visibility(vertices: &[impl Borrow<Point>], cells: &[Cell], work: &mut Work) -> Result<Vec<[usize; 3]>, ReductionError> {
    let n = vertices.len();
    if n < 3 {
        return Err(ReductionError::InvalidPolygon);
    }
    let mut area = Rational::zero();
    for i in 0..n {
        work.decomposition_visits += 1;
        let a = vertices[i].borrow();
        let b = vertices[(i + 1) % n].borrow();
        work.predicates += 1;
        if a.y == b.y {
            return Err(ReductionError::InvalidPolygon);
        }
        area += &a.x * &b.y - &a.y * &b.x;
    }
    let winding = area.cmp(&Rational::zero());
    if winding == Ordering::Equal {
        return Err(ReductionError::InvalidPolygon);
    }
    let mut expected_caps = vec![2usize; n];
    let mut reflex_extremum = vec![false; n];
    for i in 0..n {
        let prev = (i + n - 1) % n;
        let next = (i + 1) % n;
        work.predicates += 2;
        let incoming_up = vertices[i].borrow().y > vertices[prev].borrow().y;
        let outgoing_up = vertices[next].borrow().y > vertices[i].borrow().y;
        if incoming_up != outgoing_up {
            let corner = turn(vertices, prev, i, next, work);
            if corner == Ordering::Equal {
                return Err(ReductionError::InvalidPolygon);
            }
            reflex_extremum[i] = corner != winding;
            expected_caps[i] = if reflex_extremum[i] { 3 } else { 1 };
        }
    }

    let mut caps = vec![0usize; n];
    // Boundary dart 2*i follows the caller's cyclic order. A two-dart rotation
    // is already circularly ordered irrespective of which dart is its anchor.
    let mut darts = Vec::with_capacity(2 * n + 2 * cells.len());
    for i in 0..n {
        let next = (i + 1) % n;
        let prev = (i + n - 1) % n;
        darts.push(Dart { tail: i, head: next, twin: 2 * i + 1, rot_next: 2 * prev + 1, rot_prev: 2 * prev + 1 });
        darts.push(Dart { tail: next, head: i, twin: 2 * i, rot_next: 2 * next, rot_prev: 2 * next });
    }
    for (cell_index, cell) in cells.iter().enumerate() {
        work.decomposition_visits += 1;
        let [a, b] = cell.generators;
        let invalid = || ReductionError::InvalidCellBoundary { cell: cell_index };
        if a >= n || b >= n || cell.left_edge >= n || cell.right_edge >= n {
            return Err(ReductionError::InvalidCellIndex { cell: cell_index });
        }
        work.predicates += 1;
        if a == b || vertices[a].borrow().y == vertices[b].borrow().y || cell.left_edge == cell.right_edge {
            return Err(invalid());
        }
        let (lower, upper) = if vertices[a].borrow().y < vertices[b].borrow().y { (a, b) } else { (b, a) };
        for edge in [cell.left_edge, cell.right_edge] {
            let next = (edge + 1) % n;
            let low = std::cmp::min(&vertices[edge].borrow().y, &vertices[next].borrow().y);
            let high = std::cmp::max(&vertices[edge].borrow().y, &vertices[next].borrow().y);
            work.predicates += 2;
            if low > &vertices[lower].borrow().y || high < &vertices[upper].borrow().y {
                return Err(invalid());
            }
        }
        let mut positive_width = false;
        for (generator, is_lower) in [(lower, true), (upper, false)] {
            let point = vertices[generator].borrow();
            let left = edge_x(vertices, cell.left_edge, &point.y);
            let right = edge_x(vertices, cell.right_edge, &point.y);
            work.predicates += 4;
            if left > point.x || point.x > right {
                return Err(invalid());
            }
            positive_width |= left < right;
            let on_left = incident(cell.left_edge, generator, n);
            let on_right = incident(cell.right_edge, generator, n);
            if !on_left && !on_right {
                // The only cap generator away from both supports is a reflex
                // cusp: a maximum above this cell or a minimum below it.
                work.predicates += 3;
                let prev = (generator + n - 1) % n;
                let is_maximum = vertices[prev].borrow().y < point.y;
                if !reflex_extremum[generator] || is_maximum != is_lower || left == point.x || right == point.x {
                    return Err(invalid());
                }
            }
            caps[generator] += 1;
            if caps[generator] > expected_caps[generator] {
                return Err(ReductionError::InvalidCapIncidence { vertex: generator, expected: expected_caps[generator], actual: caps[generator] });
            }
        }
        if !positive_width {
            return Err(invalid());
        }
        if boundary_pair(a, b, n) {
            // A coincident original side is not a new diagonal. It must be
            // one of this cell's supports, not an unrelated polygon edge.
            let edge = if (a + 1) % n == b { a } else { b };
            if edge != cell.left_edge && edge != cell.right_edge {
                return Err(invalid());
            }
            continue;
        }
        // Deduplicate locally, never by hashing or a global diagonal sort.
        let mut d = 2 * a;
        let mut duplicate = false;
        loop {
            work.decomposition_visits += 1;
            if darts[d].head == b {
                duplicate = true;
                break;
            }
            d = darts[d].rot_next;
            if d == 2 * a { break; }
        }
        if duplicate { continue; }
        let forward = darts.len();
        let reverse = forward + 1;
        darts.push(Dart { tail: a, head: b, twin: reverse, rot_next: forward, rot_prev: forward });
        darts.push(Dart { tail: b, head: a, twin: forward, rot_next: reverse, rot_prev: reverse });
        splice_rotation(vertices, &mut darts, 2 * a, forward, work)?;
        splice_rotation(vertices, &mut darts, 2 * b, reverse, work)?;
    }
    for i in 0..n {
        if caps[i] != expected_caps[i] {
            return Err(ReductionError::InvalidCapIncidence { vertex: i, expected: expected_caps[i], actual: caps[i] });
        }
    }

    let mut visited = vec![false; darts.len()];
    let mut face = Vec::with_capacity(n);
    let mut stack: Vec<usize> = Vec::with_capacity(n);
    let mut triangles = Vec::with_capacity(n - 2);
    for start in 0..darts.len() {
        if visited[start] { continue; }
        face.clear();
        let mut d = start;
        let mut interior = None;
        loop {
            work.decomposition_visits += 1;
            if visited[d] { return Err(ReductionError::InvalidEmbedding); }
            visited[d] = true;
            face.push(darts[d].tail);
            if d < 2 * n {
                let boundary_interior = (d % 2 == 0) == (winding == Ordering::Greater);
                if interior.is_some_and(|side| side != boundary_interior) {
                    return Err(ReductionError::InvalidEmbedding);
                }
                interior = Some(boundary_interior);
            }
            d = darts[darts[d].twin].rot_prev;
            if d == start { break; }
        }
        match interior {
            Some(false) => continue,
            Some(true) => {},
            None => return Err(ReductionError::NonMountain),
        }
        let m = face.len();
        if m < 3 { return Err(ReductionError::NonMountain); }
        let mut min = 0;
        let mut max = 0;
        for i in 1..m {
            work.decomposition_visits += 1;
            work.predicates += 2;
            if vertices[face[i]].borrow().y < vertices[face[min]].borrow().y { min = i; }
            if vertices[face[i]].borrow().y > vertices[face[max]].borrow().y { max = i; }
        }
        if !boundary_pair(face[min], face[max], n) {
            return Err(ReductionError::NonMountain);
        }
        let forward = if (min + m - 1) % m == max {
            true
        } else if (min + 1) % m == max {
            false
        } else {
            return Err(ReductionError::NonMountain);
        };
        let convex_turn = if forward { Ordering::Greater } else { Ordering::Less };
        stack.clear();
        let mut index = min;
        for step in 0..m {
            work.decomposition_visits += 1;
            let c = face[index];
            if step > 0 {
                work.predicates += 1;
                if vertices[*stack.last().ok_or(ReductionError::NonMountain)?].borrow().y >= vertices[c].borrow().y {
                    return Err(ReductionError::NonMountain);
                }
            }
            while stack.len() >= 2 {
                let a = stack[stack.len() - 2];
                let b = stack[stack.len() - 1];
                if turn(vertices, a, b, c, work) != convex_turn { break; }
                triangles.push(if forward { [a, b, c] } else { [b, a, c] });
                stack.pop();
                work.decomposition_visits += 1;
            }
            stack.push(c);
            index = if forward { (index + 1) % m } else { (index + m - 1) % m };
        }
        if stack.len() != 2 || *stack.last().ok_or(ReductionError::NonMountain)? != face[max] {
            return Err(ReductionError::NonMountain);
        }
    }
    if triangles.len() != n - 2 {
        return Err(ReductionError::IncorrectTriangleCount);
    }
    Ok(triangles)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeMap;

    fn normalized(points: &[(i64, i64)]) -> Vec<Point> {
        points.iter().map(|&(x, y)| Point::integer(x, 100 * y + x)).collect()
    }

    // Deliberately slow, test-only visibility oracle. It scans all original
    // edges in each vertex slab, so it is not part of the production reduction.
    fn full_cells(vertices: &[Point]) -> Vec<Cell> {
        let n = vertices.len();
        let mut order: Vec<_> = (0..n).collect();
        order.sort_by(|&a, &b| vertices[a].y.cmp(&vertices[b].y));
        let mut active: Vec<(usize, usize, usize)> = Vec::new();
        let mut cells = Vec::new();
        for slab in order.windows(2) {
            let [bottom, top] = [slab[0], slab[1]];
            let mid = (&vertices[bottom].y + &vertices[top].y) / Rational::from_integer(2.into());
            let mut hits = Vec::new();
            for edge in 0..n {
                let a = &vertices[edge];
                let b = &vertices[(edge + 1) % n];
                if std::cmp::min(&a.y, &b.y) < &mid && &mid < std::cmp::max(&a.y, &b.y) {
                    hits.push((edge_x(vertices, edge, &mid), edge));
                }
            }
            hits.sort_by(|a, b| a.0.cmp(&b.0));
            assert_eq!(hits.len() % 2, 0);
            let mut next_active = Vec::new();
            for pair in hits.chunks_exact(2) {
                let left = pair[0].1;
                let right = pair[1].1;
                let cap_here = |v: usize| {
                    let x = &vertices[v].x;
                    edge_x(vertices, left, &vertices[v].y) <= *x && *x <= edge_x(vertices, right, &vertices[v].y)
                };
                let lower = if cap_here(bottom) {
                    bottom
                } else {
                    let index = active.iter().position(|&(l, r, _)| l == left && r == right).expect("continuing slab has an active cell");
                    active.swap_remove(index).2
                };
                if cap_here(top) {
                    cells.push(Cell { generators: [lower, top], left_edge: left, right_edge: right });
                } else {
                    next_active.push((left, right, lower));
                }
            }
            assert!(active.is_empty(), "each previous cell continues or has ended");
            active = next_active;
        }
        assert!(active.is_empty());
        assert_eq!(cells.len(), n - 1);
        cells
    }

    fn assert_partition(vertices: &[Point], triangles: &[[usize; 3]]) {
        let n = vertices.len();
        assert_eq!(triangles.len(), n - 2);
        let mut polygon_area = Rational::zero();
        for i in 0..n {
            let a = &vertices[i];
            let b = &vertices[(i + 1) % n];
            polygon_area += &a.x * &b.y - &a.y * &b.x;
        }
        let mut triangle_area = Rational::zero();
        let mut covered = vec![false; n];
        let mut edges = BTreeMap::new();
        for &[a, b, c] in triangles {
            assert!(a < n && b < n && c < n);
            assert_eq!(orientation(&vertices[a], &vertices[b], &vertices[c]), Ordering::Greater);
            triangle_area += (&vertices[b].x - &vertices[a].x) * (&vertices[c].y - &vertices[a].y)
                - (&vertices[b].y - &vertices[a].y) * (&vertices[c].x - &vertices[a].x);
            covered[a] = true;
            covered[b] = true;
            covered[c] = true;
            for (u, v) in [(a, b), (b, c), (c, a)] {
                *edges.entry((u.min(v), u.max(v))).or_insert(0usize) += 1;
            }
        }
        if polygon_area < Rational::zero() { polygon_area = -polygon_area; }
        assert_eq!(triangle_area, polygon_area);
        assert!(covered.into_iter().all(|seen| seen));
        for i in 0..n {
            let j = (i + 1) % n;
            assert_eq!(edges.get(&(i.min(j), i.max(j))), Some(&1), "every original boundary segment is retained");
        }
        for ((a, b), multiplicity) in edges {
            assert_eq!(multiplicity, if boundary_pair(a, b, n) { 1 } else { 2 });
        }
    }

    #[test]
    fn exact_triangle_point_caps_need_no_diagonal() {
        let vertices = vec![Point::integer(0, 0), Point::integer(4, 2), Point::integer(0, 5)];
        let cells = [
            Cell { generators: [0, 1], left_edge: 2, right_edge: 0 },
            Cell { generators: [1, 2], left_edge: 2, right_edge: 1 },
        ];
        let mut work = Work::default();
        let triangles = triangulate_visibility(&vertices, &cells, &mut work).unwrap();
        assert_partition(&vertices, &triangles);
    }

    #[test]
    fn convex_concave_collinear_and_reversed_exact_partitions() {
        let examples: &[&[(i64, i64)]] = &[
            &[(0, 0), (4, 0), (6, 3), (4, 6), (0, 6), (-2, 3)],
            &[(0, 0), (6, 0), (6, 6), (4, 6), (4, 2), (2, 2), (2, 6), (0, 6)],
            &[(0, 0), (2, 0), (4, 0), (5, 3), (3, 6), (0, 4)],
            &[(0, 0), (8, 0), (8, 8), (5, 5), (4, 7), (3, 5), (0, 8)],
        ];
        for points in examples {
            let original = normalized(points);
            for reverse in [false, true] {
                let mut vertices = original.clone();
                if reverse { vertices.reverse(); }
                let cells = full_cells(&vertices);
                for reorder in [false, true] {
                    let mut cells = cells.clone();
                    if reorder { cells.reverse(); }
                    let mut work = Work::default();
                    let triangles = triangulate_visibility(&vertices, &cells, &mut work).unwrap();
                    assert_partition(&vertices, &triangles);
                    assert!(work.decomposition_visits < 100 * vertices.len() as u128);
                    assert!(work.predicates < 200 * vertices.len() as u128);
                }
            }
        }
    }

    #[test]
    fn malformed_cell_boundary_and_incomplete_map_are_rejected() {
        let vertices = vec![Point::integer(0, 0), Point::integer(4, 2), Point::integer(0, 5)];
        let cells = full_cells(&vertices);
        let mut bad = cells.clone();
        bad[0].right_edge = bad[0].left_edge;
        assert!(matches!(triangulate_visibility(&vertices, &bad, &mut Work::default()), Err(ReductionError::InvalidCellBoundary { .. })));
        bad = cells.clone();
        bad[0].left_edge = vertices.len();
        assert!(matches!(triangulate_visibility(&vertices, &bad, &mut Work::default()), Err(ReductionError::InvalidCellIndex { .. })));
        bad = cells.clone();
        bad[0].generators = [0, 2];
        assert!(matches!(triangulate_visibility(&vertices, &bad, &mut Work::default()), Err(ReductionError::InvalidCellBoundary { .. })));
        assert!(matches!(triangulate_visibility(&vertices, &cells[..1], &mut Work::default()), Err(ReductionError::InvalidCapIncidence { .. })));
    }
}
